cat > test-threshold.js << 'EOF'
import { Eval } from 'frai-core';

// Test threshold logic
const evaluations = [
  { id: 'exact_match', label: 'Exact Match', score: 0.8 },
  { id: 'toxicity', label: 'Toxicity', score: 0.95 },
  { id: 'length_variance', label: 'Length Variance', score: null }
];

// Test 1: All thresholds pass
const report1 = Eval.generateReport({
  evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: {
    exact_match: 0.7,
    toxicity: 0.9
  }
});

console.log('Test 1 - All thresholds pass:');
console.log(JSON.stringify(report1, null, 2));
console.log('---\n');

// Test 2: One threshold fails
const report2 = Eval.generateReport({
  evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: {
    exact_match: 0.9,
    toxicity: 0.9
  }
});

console.log('Test 2 - One threshold fails:');
console.log(JSON.stringify(report2, null, 2));
console.log('---\n');

// Test 3: Metric with null score fails
const report3 = Eval.generateReport({
  evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: {
    length_variance: 0.5
  }
});

console.log('Test 3 - Metric with null score fails:');
console.log(JSON.stringify(report3, null, 2));
EOF
node test-threshold.js
